local function _abswcut(s,cnt)local o={}for i=0,cnt-1 do local p=i*4+1 o[i+1]=byte(s,p)+byte(s,p+1)*256+byte(s,p+2)*65536+byte(s,p+3)*16777216 end return o end local function _lstzrilkq(w)local o={}for i=1,#w do local v=w[i]o[i]=char(v%256,rs(v,8)%256,rs(v,16)%256,rs(v,24)%256)end return concat(o)end
local function _yxjfxcthl(x,a,b,c,d)x[a]=(x[a]+x[b])%4294967296 x[d]=lr(bx(x[d],x[a]),16)x[c]=(x[c]+x[d])%4294967296 x[b]=lr(bx(x[b],x[c]),12)x[a]=(x[a]+x[b])%4294967296 x[d]=lr(bx(x[d],x[a]),8)x[c]=(x[c]+x[d])%4294967296 x[b]=lr(bx(x[b],x[c]),7)end local function _quctnbne(x)for _=1,10 do _yxjfxcthl(x,1,5,9,13)_yxjfxcthl(x,2,6,10,14)_yxjfxcthl(x,3,7,11,15)_yxjfxcthl(x,4,8,12,16)_yxjfxcthl(x,1,6,11,16)_yxjfxcthl(x,2,7,12,13)_yxjfxcthl(x,3,8,9,14)_yxjfxcthl(x,4,5,10,15)end end
local function _kleparrgojf(s,key,nonce)local kw2=_abswcut(key,8)local nw=_abswcut(nonce,6)local x={1634760805,857760878,2036477234,1797285236}for i=1,8 do x[4+i]=kw2[i]end for i=1,4 do x[12+i]=nw[i]end _quctnbne(x)local subkey={x[1],x[2],x[3],x[4],x[13],x[14],x[15],x[16]}local no=char(0,0,0,0)..nonce:sub(17,24)local nn=_abswcut(no,3)local o={}local q=0 for off=1,#s,64 do local init={1634760805,857760878,2036477234,1797285236}for i=1,8 do init[4+i]=subkey[i]end init[13]=floor((off-1)/64)+1 init[14],init[15],init[16]=nn[1],nn[2],nn[3]local z={}for i=1,16 do z[i]=init[i]end _quctnbne(z)for i=1,16 do z[i]=(z[i]+init[i])%4294967296 end local stream=_lstzrilkq(z)for i=0,math.min(63,#s-off)do q=q+1 o[q]=char(bx(byte(s,off+i),byte(stream,i+1)))end end return concat(o)end
